# --- your code ---
def encode(root: "TreeNode | None") -> str:
    tokens = []
    def walk(node: "TreeNode | None") -> None:
        if node is None:
            tokens.append("#")            # the marker keeps the shape: a leaf is "v,#,#"
            return
        tokens.append(str(node.val))
        walk(node.left)
        walk(node.right)
    walk(root)
    return ",".join(tokens)


def decode(text: str) -> "TreeNode | None":
    tokens = iter(text.split(","))
    def read() -> "TreeNode | None":
        token = next(tokens)
        if token == "#":
            return None
        node = TreeNode(int(token))
        node.left = read()                # same order as encode: node, left, right
        node.right = read()
        return node
    return read()


